export function usePath<T>(store: Store<any>, path: YPath, selector: (value: any) => T = (v) => v as T): T {
  return useSyncExternalStore(
    (onChange) =>
      store.onPathChanged(path, (cb) => {
        cb();
        onChange();
        return () => {};
      }),
    () => selector(store.getPathSnapshot(path)),
  );
}
